          "code": "import numpy as np\nfrom sklearn.tree import DecisionTreeRegressor\n\nrng = np.random.default_rng(42)\n\n# 1) Regresi non-linier 1D dengan 8% outlier target ekstrem (uji MSE vs MAE pseudo-residual)\nn_tr, n_te = 260, 200\nX_tr = rng.uniform(-3.0, 3.0, size=(n_tr, 1))\ny_clean = 2.0 * np.sin(1.4 * X_tr[:, 0]) + 0.35 * X_tr[:, 0] ** 2\ny_tr = y_clean + rng.normal(0.0, 0.25, size=n_tr)\n# Suntikkan 8% outlier ekstrem (+18 hingga +25) hanya di data latih\noutlier_idx = rng.choice(n_tr, size=int(0.08 * n_tr), replace=False)\ny_tr[outlier_idx] += rng.uniform(18.0, 25.0, size=len(outlier_idx))\n\nX_te = np.linspace(-2.9, 2.9, n_te).reshape(-1, 1)\ny_te = 2.0 * np.sin(1.4 * X_te[:, 0]) + 0.35 * X_te[:, 0] ** 2\n\n\ndef fit_friedman_gbm(X, y, loss=\"mse\", n_estimators=45, lr=0.12, max_depth=3):\n    \"\"\"Implementasi Functional Gradient Descent Friedman (2001) + exact per-leaf line search.\"\"\"\n    if loss == \"mse\":\n        f0 = float(np.mean(y))\n    elif loss == \"mae\":\n        f0 = float(np.median(y))\n    elif loss == \"log_loss\":\n        p_bar = np.clip(float(np.mean(y)), 1e-6, 1.0 - 1e-6)\n        f0 = float(np.log(p_bar / (1.0 - p_bar)))\n    else:\n        raise ValueError(loss)\n\n    F = np.full(len(y), f0, dtype=float)\n    stages = []\n    for m in range(n_estimators):\n        if loss == \"mse\":\n            pseudo_res = y - F\n        elif loss == \"mae\":\n            pseudo_res = np.sign(y - F)\n        else:\n            p = 1.0 / (1.0 + np.exp(-np.clip(F, -30.0, 30.0)))\n            pseudo_res = y - p\n\n        tree = DecisionTreeRegressor(max_depth=max_depth, random_state=42 + m)\n        tree.fit(X, pseudo_res)\n        leaf_ids = tree.apply(X)\n        leaf_gamma = {}\n        for lid in np.unique(leaf_ids):\n            mask = leaf_ids == lid\n            if loss == \"mse\":\n                gamma = float(np.mean(y[mask] - F[mask]))\n            elif loss == \"mae\":\n                gamma = float(np.median(y[mask] - F[mask]))\n            else:\n                p_m = 1.0 / (1.0 + np.exp(-np.clip(F[mask], -30.0, 30.0)))\n                denom = float(np.sum(p_m * (1.0 - p_m))) + 1e-12\n                gamma = float(np.sum(y[mask] - p_m)) / denom\n            leaf_gamma[int(lid)] = gamma\n            F[mask] += lr * gamma\n        stages.append((tree, leaf_gamma))\n    return f0, stages\n\n\ndef predict_friedman_gbm(f0, stages, X, lr=0.12):\n    F = np.full(len(X), f0, dtype=float)\n    for tree, leaf_gamma in stages:\n        lids = tree.apply(X)\n        F += lr * np.array([leaf_gamma[int(lid)] for lid in lids], dtype=float)\n    return F\n\n\nf0_mse, st_mse = fit_friedman_gbm(X_tr, y_tr, loss=\"mse\", n_estimators=45, lr=0.12)\nf0_mae, st_mae = fit_friedman_gbm(X_tr, y_tr, loss=\"mae\", n_estimators=45, lr=0.12)\npred_mse = predict_friedman_gbm(f0_mse, st_mse, X_te, lr=0.12)\npred_mae = predict_friedman_gbm(f0_mae, st_mae, X_te, lr=0.12)\n\n# 2) Klasifikasi Biner Log-Loss (y in {0, 1}) — verifikasi F0 = log-odds & Newton leaf step\nX_cls = rng.normal(0.0, 1.0, size=(320, 3))\nlogits_true = -1.1 + 1.5 * X_cls[:, 0] - 1.2 * (X_cls[:, 1] ** 2) + 0.9 * X_cls[:, 0] * X_cls[:, 2]\np_true = 1.0 / (1.0 + np.exp(-logits_true))\ny_cls = (rng.uniform(0.0, 1.0, size=320) < p_true).astype(float)\nf0_ll, st_ll = fit_friedman_gbm(X_cls[:220], y_cls[:220], loss=\"log_loss\", n_estimators=40, lr=0.12)\nF_te_ll = predict_friedman_gbm(f0_ll, st_ll, X_cls[220:], lr=0.12)\np_te_ll = 1.0 / (1.0 + np.exp(-np.clip(F_te_ll, -30.0, 30.0)))\nll_init = float(-np.mean(y_cls[220:] * np.log(1 / (1 + np.exp(-f0_ll))) + (1 - y_cls[220:]) * np.log(1 - 1 / (1 + np.exp(-f0_ll)))))\nll_final = float(-np.mean(y_cls[220:] * np.log(np.clip(p_te_ll, 1e-9, 1 - 1e-9)) + (1 - y_cls[220:]) * np.log(np.clip(1 - p_te_ll, 1e-9, 1 - 1e-9))))\nacc_ll = float(np.mean((p_te_ll >= 0.5) == y_cls[220:]))\n\nprint(\"=== Friedman Functional Gradient Descent dari Nol (8% Outlier Target Latih) ===\")\nprint(f\"MSE (r = y - F, leaf = mean)   | F0={f0_mse:+.4f} | Clean Test MAE={np.mean(np.abs(y_te - pred_mse)):.4f} | RMSE={np.sqrt(np.mean((y_te - pred_mse)**2)):.4f}\")\nprint(f\"MAE (r = sign, leaf = median)  | F0={f0_mae:+.4f} | Clean Test MAE={np.mean(np.abs(y_te - pred_mae)):.4f} | RMSE={np.sqrt(np.mean((y_te - pred_mae)**2)):.4f}\")\nprint(\"=== Klasifikasi Log-Loss (r = y - p, leaf = sum(y-p) / sum(p(1-p))) ===\")\nprint(f\"F0 log-odds={f0_ll:+.4f} (base_rate={y_cls[:220].mean():.3f}) | Test LogLoss: {ll_init:.4f} -> {ll_final:.4f} | Test Acc={acc_ll:.3f}\")",
