          "code": "import numpy as np\nfrom sklearn.ensemble import GradientBoostingClassifier, GradientBoostingRegressor\nfrom sklearn.metrics import log_loss, mean_absolute_error, roc_auc_score, root_mean_squared_error\nfrom sklearn.model_selection import train_test_split\n\nrng = np.random.default_rng(151)\nn = 900\n\n# Simulasi prediksi ETA pengiriman logistik (jam) dengan 4% paket tertahan ekstrem di gudang\ndist_km = rng.uniform(2.0, 45.0, size=n)\ntraffic_idx = rng.uniform(0.5, 2.5, size=n)\nn_stops = rng.integers(1, 14, size=n).astype(float)\nrain_mm = rng.exponential(3.5, size=n)\nX = np.column_stack([dist_km, traffic_idx, n_stops, rain_mm])\n\neta_true = 1.2 + 0.08 * dist_km * traffic_idx + 0.18 * n_stops + 0.45 * np.log1p(rain_mm)\ny_clean = eta_true + rng.normal(0.0, 0.35, size=n)\n\nX_tr, X_te, y_tr_clean, y_te_clean = train_test_split(X, y_clean, test_size=0.30, random_state=42)\n# Hanya data latih terkontaminasi 4% tiket tertahan bea cukai/gudang (+48 s.d. +96 jam)\ny_tr_noisy = y_tr_clean.copy()\nspike_idx = rng.choice(len(y_tr_noisy), size=int(0.04 * len(y_tr_noisy)), replace=False)\ny_tr_noisy[spike_idx] += rng.uniform(48.0, 96.0, size=len(spike_idx))\n\nprint(\"=== Scikit-Learn 1.9 GradientBoostingRegressor: MSE vs MAE vs Huber pada 4% Outlier ETA ===\")\nprint(\"Loss Function    | Clean Test MAE | Clean Test RMSE | Max Abs Error (jam)\")\nprint(\"-\" * 74)\nfor loss_name in (\"squared_error\", \"absolute_error\", \"huber\"):\n    kwargs = {\"alpha\": 0.90} if loss_name == \"huber\" else {}\n    reg = GradientBoostingRegressor(\n        loss=loss_name, n_estimators=90, learning_rate=0.08, max_depth=3, random_state=42, **kwargs\n    ).fit(X_tr, y_tr_noisy)\n    pred = reg.predict(X_te)\n    print(\n        f\"{loss_name:16s} | {mean_absolute_error(y_te_clean, pred):14.4f} | \"\n        f\"{root_mean_squared_error(y_te_clean, pred):15.4f} | {float(np.max(np.abs(y_te_clean - pred))):19.4f}\"\n    )\n\n# Verifikasi GradientBoostingClassifier(loss=\"log_loss\"): F0 log-odds & penurunan deviance\ny_late = (y_clean > np.quantile(y_clean, 0.78)).astype(int)\nXc_tr, Xc_te, yc_tr, yc_te = train_test_split(X, y_late, test_size=0.30, stratify=y_late, random_state=42)\nclf = GradientBoostingClassifier(\n    loss=\"log_loss\", n_estimators=80, learning_rate=0.08, max_depth=3, random_state=42\n).fit(Xc_tr, yc_tr)\np_hat = clf.predict_proba(Xc_te)[:, 1]\nf0_manual = float(np.log(yc_tr.mean() / (1.0 - yc_tr.mean())))\nf0_sklearn = float(clf.init_.predict_proba(Xc_te[:1])[0, 1])\nf0_sklearn_logit = float(np.log(f0_sklearn / (1.0 - f0_sklearn)))\n\nprint(\"-\" * 74)\nprint(\"=== Verifikasi Log-Loss GBDT (Target Keterlambatan > Persentil 78) ===\")\nprint(f\"F0 Log-Odds Manual vs Sklearn init_ : {f0_manual:+.6f} vs {f0_sklearn_logit:+.6f} (gap={abs(f0_manual - f0_sklearn_logit):.1e})\")\nprint(f\"Test Log-Loss={log_loss(yc_te, p_hat):.4f} | Test AUROC={roc_auc_score(yc_te, p_hat):.4f} | Mean(p)={p_hat.mean():.4f} (actual={yc_te.mean():.4f})\")",
