          "code": "import numpy as np\nfrom sklearn.tree import DecisionTreeRegressor\n\nrng = np.random.default_rng(77)\n\n# Uji dampak melupakan Friedman Per-Leaf Line Search pada klasifikasi kelas timpang (base rate ~2.5%)\nn_tr, n_te = 800, 400\nX = rng.normal(0.0, 1.0, size=(n_tr + n_te, 4))\nlogits_true = -4.2 + 1.8 * X[:, 0] - 1.5 * X[:, 1] + 1.2 * (X[:, 0] * X[:, 2])\np_true = 1.0 / (1.0 + np.exp(-logits_true))\ny = (rng.uniform(0.0, 1.0, size=n_tr + n_te) < p_true).astype(float)\n\nX_tr, y_tr = X[:n_tr], y[:n_tr]\nX_te, y_te = X[n_tr:], y[n_tr:]\n\ndef binary_log_loss(yt, F):\n    p = 1.0 / (1.0 + np.exp(-np.clip(F, -30.0, 30.0)))\n    return float(-np.mean(yt * np.log(np.clip(p, 1e-12, 1 - 1e-12)) + (1 - yt) * np.log(np.clip(1 - p, 1e-12, 1 - 1e-12))))\n\ndef run_logloss_boosting(use_newton_leaf: bool, n_rounds=50, lr=0.1):\n    p0 = np.clip(float(np.mean(y_tr)), 1e-6, 1 - 1e-6)\n    f0 = float(np.log(p0 / (1.0 - p0)))\n    F_tr = np.full(n_tr, f0, dtype=float)\n    F_te = np.full(n_te, f0, dtype=float)\n    for m in range(n_rounds):\n        p = 1.0 / (1.0 + np.exp(-np.clip(F_tr, -30.0, 30.0)))\n        r = y_tr - p\n        tree = DecisionTreeRegressor(max_depth=3, min_samples_leaf=15, random_state=100 + m).fit(X_tr, r)\n        if not use_newton_leaf:\n            # BUG: menambahkan mean(y - p) langsung tanpa pembagi Hessian sum(p(1-p))!\n            F_tr += lr * tree.predict(X_tr)\n            F_te += lr * tree.predict(X_te)\n        else:\n            lids_tr = tree.apply(X_tr)\n            lids_te = tree.apply(X_te)\n            gamma_map = {}\n            for lid in np.unique(lids_tr):\n                mask = lids_tr == lid\n                denom = float(np.sum(p[mask] * (1.0 - p[mask]))) + 1e-12\n                gamma_map[int(lid)] = float(np.sum(r[mask])) / denom\n            F_tr += lr * np.array([gamma_map[int(l)] for l in lids_tr])\n            F_te += lr * np.array([gamma_map[int(l)] for l in lids_te])\n    return binary_log_loss(y_tr, F_tr), binary_log_loss(y_te, F_te), float(np.std(F_te))\n\np0 = float(np.mean(y_tr))\nbase_ll = binary_log_loss(y_te, np.full(n_te, np.log(p0 / (1.0 - p0))))\ntr_naive, te_naive, std_naive = run_logloss_boosting(use_newton_leaf=False)\ntr_newton, te_newton, std_newton = run_logloss_boosting(use_newton_leaf=True)\n\n# Diagnostik kedua: perbandingan rasio skala 1/(p(1-p)) pada berbagai prevalensi\nprint(f\"=== Diagnostik Line Search Per-Daun Log-Loss (Base Rate={p0:.2%}, Baseline Test LL={base_ll:.4f}) ===\")\nprint(f\"Tanpa Newton Leaf (hanya mean(y-p))        | Train LL={tr_naive:.4f} | Test LL={te_naive:.4f} | std(F_te)={std_naive:.4f} (STALL!)\")\nprint(f\"Dengan Newton Leaf (sum(y-p)/sum(p(1-p)))  | Train LL={tr_newton:.4f} | Test LL={te_newton:.4f} | std(F_te)={std_newton:.4f} (KONVERGEN)\")\nprint(\"--- Pengganda Skala Hessian 1 / [p(1-p)] yang Hilang Tanpa Line Search ---\")\nfor prev in (0.50, 0.10, 0.02, 0.005):\n    mult = 1.0 / (prev * (1.0 - prev))\n    print(f\"  Prevalensi p={prev:5.1%} -> p(1-p)={prev*(1-prev):.5f} -> Langkah Newton {mult:6.1f}x lebih tajam dari raw mean(y-p)!\")",
