          "code": "import numpy as np\nfrom sklearn.ensemble import GradientBoostingRegressor, HistGradientBoostingRegressor\nfrom sklearn.metrics import root_mean_squared_error\nfrom sklearn.model_selection import KFold\n\nrng = np.random.default_rng(152)\nn, d = 650, 8\nX = rng.normal(0.0, 1.0, size=(n, d))\ny = (\n    2.2 * X[:, 0] * X[:, 1]\n    - 1.6 * np.sin(1.8 * X[:, 2])\n    + 1.3 * np.abs(X[:, 3])\n    + 0.7 * X[:, 4] ** 2\n    + rng.normal(0.0, 1.1, size=n)\n)\n\n# Evaluasi 3-fold CV murni: early stopping terjadi DI DALAM masing-masing lipatan latih!\nkf = KFold(n_splits=3, shuffle=True, random_state=42)\n\nmodels = {\n    \"GBR Tanpa EarlyStop (M=180, lr=0.18)\": lambda: GradientBoostingRegressor(\n        n_estimators=180, learning_rate=0.18, subsample=1.0, max_depth=3, random_state=42\n    ),\n    \"GBR Stoch+EarlyStop (sub=0.75, lr=0.06)\": lambda: GradientBoostingRegressor(\n        n_estimators=220,\n        learning_rate=0.06,\n        subsample=0.75,\n        max_depth=3,\n        validation_fraction=0.15,\n        n_iter_no_change=10,\n        tol=1e-4,\n        random_state=42,\n    ),\n    \"HistGBR EarlyStop (lr=0.06, pat=10)\": lambda: HistGradientBoostingRegressor(\n        max_iter=220,\n        learning_rate=0.06,\n        max_leaf_nodes=15,\n        l2_regularization=1.0,\n        early_stopping=True,\n        validation_fraction=0.15,\n        n_iter_no_change=10,\n        random_state=42,\n    ),\n}\n\nprint(\"=== Audit 3-Fold CV Bebas-Kebocoran: Early Stopping Internal vs Tanpa Early Stopping ===\")\nprint(\"Model                                    | Mean CV RMSE | Std RMSE | Mean Pohon Terpakai\")\nprint(\"-\" * 88)\nfor name, factory in models.items():\n    rmses, used_trees = [], []\n    for tr_idx, va_idx in kf.split(X):\n        est = factory()\n        est.fit(X[tr_idx], y[tr_idx])\n        pred = est.predict(X[va_idx])\n        rmses.append(float(root_mean_squared_error(y[va_idx], pred)))\n        n_used = int(est.n_estimators_) if hasattr(est, \"n_estimators_\") else int(est.n_iter_)\n        used_trees.append(n_used)\n    print(f\"{name:40s} | {np.mean(rmses):12.4f} | {np.std(rmses):8.4f} | {np.mean(used_trees):19.1f}\")",
          "expectedOutput": "=== Audit 3-Fold CV Bebas-Kebocoran: Early Stopping Internal vs Tanpa Early Stopping ===\nModel                                    | Mean CV RMSE | Std RMSE | Mean Pohon Terpakai\n----------------------------------------------------------------------------------------\nGBR Tanpa EarlyStop (M=180, lr=0.18)     |       2.0536 |   0.0852 |               180.0\nGBR Stoch+EarlyStop (sub=0.75, lr=0.06)  |       2.1964 |   0.2534 |               133.0\nHistGBR EarlyStop (lr=0.06, pat=10)      |       2.0618 |   0.2148 |               141.0",
          "actualOutput": "=== Audit 3-Fold CV Bebas-Kebocoran: Early Stopping Internal vs Tanpa Early Stopping ===\nModel                                    | Mean CV RMSE | Std RMSE | Mean Pohon Terpakai\n----------------------------------------------------------------------------------------\nGBR Tanpa EarlyStop (M=180, lr=0.18)     |       2.0536 |   0.0852 |               180.0\nGBR Stoch+EarlyStop (sub=0.75, lr=0.06)  |       2.1964 |   0.2534 |               133.0\nHistGBR EarlyStop (lr=0.06, pat=10)      |       2.0618 |   0.2148 |               141.0",
