          "filename": "15_2_selection_bias_lockbox_audit.py",
          "code": "import numpy as np\nfrom sklearn.ensemble import GradientBoostingRegressor\nfrom sklearn.metrics import root_mean_squared_error\n\n# Audit Monte Carlo Selection Bias: Mengintip staged_predict(X_test) vs Lockbox Murni vs Internal Early Stopping\nrng = np.random.default_rng(55)\nn_trials = 8\nleaky_reported, leaky_true_lockbox, safe_internal_lockbox = [], [], []\nchosen_m_leaky, chosen_m_safe = [], []\n\nfor trial in range(n_trials):\n    # Dataset ber-noise moderat dengan test slice kecil (n_test=100) — skenario klasik leakage!\n    X_all = rng.normal(0.0, 1.0, size=(600, 6))\n    y_all = (\n        1.6 * np.sin(X_all[:, 0])\n        + 1.2 * X_all[:, 1] * X_all[:, 2]\n        - 0.8 * X_all[:, 3]\n        + rng.normal(0.0, 1.25, size=600)\n    )\n    X_tr, y_tr = X_all[:240], y_all[:240]\n    X_te, y_te = X_all[240:340], y_all[240:340]       # 100 baris yang \"diintip\" secara ilegal\n    X_lock, y_lock = X_all[340:], y_all[340:]         # 260 baris lockbox produksi sejati\n\n    # 1) ANTI-PATTERN: latih 160 pohon, lalu intip staged_predict(X_te) untuk memilih best_M\n    gbr_full = GradientBoostingRegressor(\n        n_estimators=160, learning_rate=0.10, max_depth=3, subsample=0.8, random_state=trial\n    ).fit(X_tr, y_tr)\n    te_curve = [float(root_mean_squared_error(y_te, p)) for p in gbr_full.staged_predict(X_te)]\n    lock_curve = [float(root_mean_squared_error(y_lock, p)) for p in gbr_full.staged_predict(X_lock)]\n    best_idx = int(np.argmin(te_curve))\n    leaky_reported.append(te_curve[best_idx])\n    leaky_true_lockbox.append(lock_curve[best_idx])\n    chosen_m_leaky.append(best_idx + 1)\n\n    # 2) PRODUCTION-SAFE: internal early stopping di dalam X_tr (X_te & X_lock tak pernah disentuh!)\n    gbr_safe = GradientBoostingRegressor(\n        n_estimators=160,\n        learning_rate=0.10,\n        max_depth=3,\n        subsample=0.8,\n        validation_fraction=0.20,\n        n_iter_no_change=10,\n        random_state=trial,\n    ).fit(X_tr, y_tr)\n    safe_internal_lockbox.append(float(root_mean_squared_error(y_lock, gbr_safe.predict(X_lock))))\n    chosen_m_safe.append(int(gbr_safe.n_estimators_))\n\nrep_mean = float(np.mean(leaky_reported))\ntrue_mean = float(np.mean(leaky_true_lockbox))\nsafe_mean = float(np.mean(safe_internal_lockbox))\nbias_gap = true_mean - rep_mean\n\nprint(f\"=== Audit Monte Carlo Selection Bias Early Stopping ({n_trials} replikasi, n_test=100) ===\")\nprint(f\"1. BUG  staged_predict(X_test) — Skor Terlapor (Optimis Semu) : RMSE={rep_mean:.4f} (mean M={np.mean(chosen_m_leaky):.1f})\")\nprint(f\"2. REAL staged_predict(X_test) — Skor Nyata di Lockbox        : RMSE={true_mean:.4f} (Selection Bias={bias_gap:+.4f})\")\nprint(f\"3. SAFE Internal early_stopping — Skor Nyata di Lockbox       : RMSE={safe_mean:.4f} (mean M={np.mean(chosen_m_safe):.1f})\")\nprint(f\"Kesimpulan Audit: Mengintip X_test menyembunyikan degradasi nyata sebesar {100.0 * bias_gap / rep_mean:+.2f}%!\")",
