          "code": "import numpy as np\n\nrng = np.random.default_rng(153)\nN, D, B = 1500, 6, 255\nlam = 1.0\n\n# 1) Bangkitkan fitur kontinu dan kuantisasi sekali saja menjadi uint8 [0..254] (kompresi 8x)\nX_float = rng.normal(0.0, 1.0, size=(N, D))\nX_binned = np.empty((N, D), dtype=np.uint8)\nbin_edges = []\nquantiles = np.linspace(0.0, 1.0, B + 1)[1:-1]\nfor j in range(D):\n    edges = np.unique(np.quantile(X_float[:, j], quantiles))\n    X_binned[:, j] = np.searchsorted(edges, X_float[:, j], side=\"right\").astype(np.uint8)\n    bin_edges.append(edges)\n\n# Gradien & Hessian orde-2 (mis. dari residual regresi / log-loss)\ny_true = 2.0 * (X_float[:, 2] > 0.35).astype(float) - 1.5 * X_float[:, 0] + rng.normal(0, 0.4, N)\nf_curr = np.zeros(N, dtype=float)\ng = f_curr - y_true          # turunan pertama dL/dF untuk 0.5*(y - F)^2\nh = np.ones(N, dtype=float)  # turunan kedua d^2L/dF^2 = 1\n\ndef build_hist(X_bin_subset, g_sub, h_sub, n_bins=B):\n    d_local = X_bin_subset.shape[1]\n    G_hist = np.zeros((d_local, n_bins), dtype=np.float64)\n    H_hist = np.zeros((d_local, n_bins), dtype=np.float64)\n    for j in range(d_local):\n        G_hist[j] = np.bincount(X_bin_subset[:, j], weights=g_sub, minlength=n_bins)\n        H_hist[j] = np.bincount(X_bin_subset[:, j], weights=h_sub, minlength=n_bins)\n    return G_hist, H_hist\n\ndef scan_best_split(G_hist, H_hist, reg_lambda=1.0):\n    best_gain, best_feat, best_bin = -1.0, -1, -1\n    for j in range(G_hist.shape[0]):\n        G_tot, H_tot = float(G_hist[j].sum()), float(H_hist[j].sum())\n        parent_score = (G_tot ** 2) / (H_tot + reg_lambda)\n        G_L = np.cumsum(G_hist[j][:-1])\n        H_L = np.cumsum(H_hist[j][:-1])\n        G_R = G_tot - G_L\n        H_R = H_tot - H_L\n        valid = (H_L >= 20.0) & (H_R >= 20.0)\n        if not np.any(valid):\n            continue\n        gains = 0.5 * ((G_L ** 2) / (H_L + reg_lambda) + (G_R ** 2) / (H_R + reg_lambda) - parent_score)\n        gains = np.where(valid, gains, -1.0)\n        b_star = int(np.argmax(gains))\n        if float(gains[b_star]) > best_gain:\n            best_gain, best_feat, best_bin = float(gains[b_star]), j, b_star\n    return best_feat, best_bin, best_gain\n\n# Bangun histogram induk, lalu belah tak seimbang (mis. 24% kiri vs 76% kanan pada fitur 0)\nG_par, H_par = build_hist(X_binned, g, h)\nleft_mask = X_binned[:, 0] <= 60  # anak lebih kecil (~24% sampel)\nright_mask = ~left_mask           # anak lebih besar (~76% sampel)\n\n# Bangun histogram HANYA untuk anak kecil, lalu turunkan anak besar via SUBTRAKSI!\nG_small, H_small = build_hist(X_binned[left_mask], g[left_mask], h[left_mask])\nG_large_sub = G_par - G_small\nH_large_sub = H_par - H_small\n\n# Bandingkan terhadap pembangunan langsung (brute-force) pada anak besar\nG_large_direct, H_large_direct = build_hist(X_binned[right_mask], g[right_mask], h[right_mask])\nmax_diff_G = float(np.max(np.abs(G_large_sub - G_large_direct)))\nmax_diff_H = float(np.max(np.abs(H_large_sub - H_large_direct)))\n\nf_sub, b_sub, gain_sub = scan_best_split(G_large_sub, H_large_sub, lam)\nf_dir, b_dir, gain_dir = scan_best_split(G_large_direct, H_large_direct, lam)\n\nmem_ratio = X_float.nbytes / X_binned.nbytes\nrows_saved_pct = 100.0 * float(np.sum(right_mask)) / N\n\nprint(\"=== Verifikasi Quantile Binning uint8 (B=255) & Histogram Subtraction Trick ===\")\nprint(f\"Kompresi RAM Matriks Fitur  : float64={X_float.nbytes} B vs uint8={X_binned.nbytes} B (rasio {mem_ratio:.1f}x lebih hemat)\")\nprint(f\"Ukuran Anak Kecil vs Besar  : {int(np.sum(left_mask))} vs {int(np.sum(right_mask))} baris (hemat {rows_saved_pct:.1f}% scan baris!)\")\nprint(f\"Max |Hist_sub - Hist_direct|: dG={max_diff_G:.2e}, dH={max_diff_H:.2e} (IDENTIK EKSAK!)\")\nprint(f\"Best Split Anak Besar (Sub) : feat={f_sub}, bin={b_sub}, gain={gain_sub:.4f}\")\nprint(f\"Best Split Anak Besar (Dir) : feat={f_dir}, bin={b_dir}, gain={gain_dir:.4f} (gap={abs(gain_sub - gain_dir):.2e})\")",
