          "code": "import numpy as np\nfrom sklearn.ensemble import GradientBoostingRegressor, HistGradientBoostingRegressor\nfrom sklearn.metrics import root_mean_squared_error\nfrom sklearn.model_selection import train_test_split\n\nrng = np.random.default_rng(315)\nN, D = 900, 12\nX = rng.normal(0.0, 1.0, size=(N, D))\n# Sinyal non-linier tajam bergantung pada 5 fitur utama + 7 fitur pengganggu\ny = (\n    2.4 * np.sin(1.7 * X[:, 0])\n    + 1.6 * (X[:, 1] * X[:, 2])\n    - 1.8 * (X[:, 3] > 0.65).astype(float)\n    + 0.9 * np.abs(X[:, 4])\n    + rng.normal(0.0, 0.45, size=N)\n)\nX_tr, X_te, y_tr, y_te = train_test_split(X, y, test_size=0.25, random_state=42)\nn_tr = len(X_tr)\n\n# Bandingkan Exact GBDT vs HistGBDT pada resolusi B=255, B=64, B=16\nconfigs = [\n    (\"Exact GBDT (presorted, max_leaf=15)\", GradientBoostingRegressor(\n        n_estimators=65, learning_rate=0.09, max_leaf_nodes=15, max_depth=None, min_samples_leaf=20, random_state=42\n    ), n_tr),\n    (\"HistGBDT (max_bins=255, max_leaf=15)\", HistGradientBoostingRegressor(\n        max_iter=65, learning_rate=0.09, max_leaf_nodes=15, min_samples_leaf=20, max_bins=255, early_stopping=False, random_state=42\n    ), 255),\n    (\"HistGBDT (max_bins=64,  max_leaf=15)\", HistGradientBoostingRegressor(\n        max_iter=65, learning_rate=0.09, max_leaf_nodes=15, min_samples_leaf=20, max_bins=64, early_stopping=False, random_state=42\n    ), 64),\n    (\"HistGBDT (max_bins=16,  max_leaf=15)\", HistGradientBoostingRegressor(\n        max_iter=65, learning_rate=0.09, max_leaf_nodes=15, min_samples_leaf=20, max_bins=16, early_stopping=False, random_state=42\n    ), 16),\n]\n\nprint(f\"=== Komparasi Exact GBDT vs HistGBDT Lintas Resolusi Bin (N_tr={n_tr}, D={D}) ===\")\nprint(\"Model                                | Max Kandidat/Simpul | Train RMSE | Test RMSE\")\nprint(\"-\" * 85)\nfor label, model, max_cand in configs:\n    model.fit(X_tr, y_tr)\n    tr_rmse = float(root_mean_squared_error(y_tr, model.predict(X_tr)))\n    te_rmse = float(root_mean_squared_error(y_te, model.predict(X_te)))\n    print(f\"{label:36s} | {max_cand * D:19d} | {tr_rmse:10.4f} | {te_rmse:9.4f}\")",
