          "code": "import numpy as np\nfrom sklearn.ensemble import HistGradientBoostingClassifier\nfrom sklearn.metrics import average_precision_score, recall_score\nfrom sklearn.model_selection import train_test_split\n\nrng = np.random.default_rng(909)\nN = 1500\n\n# Simulasi nilai transfer perbankan berekor Pareto berat (Rp 100 ribu s.d. Rp 40 miliar)\namount = 100.0 * (rng.pareto(a=1.35, size=N) + 1.0)\nvelocity = rng.poisson(3.0, size=N).astype(float)\nacct_age = rng.uniform(1.0, 1200.0, size=N)\n\n# Audit 1: Pemanfaatan bin Uniform vs Quantile (255 bins) pada distribusi Pareto\nunif_edges = np.linspace(amount.min(), amount.max(), 256)[1:-1]\nunif_bins = np.searchsorted(unif_edges, amount, side=\"right\")\nquant_edges = np.unique(np.quantile(amount, np.linspace(0.0, 1.0, 256)[1:-1]))\nquant_bins = np.searchsorted(quant_edges, amount, side=\"right\")\n\npct_in_bin0_unif = 100.0 * float(np.mean(unif_bins == 0))\npct_in_bin0_quant = 100.0 * float(np.mean(quant_bins == 0))\n\n# Audit 2: Titik buta bin terakhir pada distribusi Pareto (uji max_bins=32 agar >=25 sampel di ekor)\np996 = float(np.quantile(amount, 1.0 - 1.0 / 255.0))\ntail_vals = amount[amount >= p996]\n# Ambang regulasi AML duduk di persentil 98.4% (tepat di tengah bin teratas max_bins=32: top 3.125%)\ncrit_thresh = float(np.quantile(amount, 0.984))\n\n# Label risiko tinggi dipicu kuat jika amount > crit_thresh ATAU kombinasi velocity ekstrem + akun baru\nrisk_logit = -4.2 + 5.8 * (amount > crit_thresh) + 0.55 * velocity - 0.0025 * acct_age\ny = (rng.uniform(0.0, 1.0, size=N) < 1.0 / (1.0 + np.exp(-risk_logit))).astype(int)\n\nX_raw = np.column_stack([amount, velocity, acct_age])\n# Mitigasi: tambahkan fitur batas domain eksplisit (amount > crit_thresh) + log1p(amount)\nX_mitigated = np.column_stack([amount, np.log1p(amount), (amount > crit_thresh).astype(float), velocity, acct_age])\n\nidx = np.arange(N)\ntr_i, te_i = train_test_split(idx, test_size=0.30, stratify=(amount > crit_thresh).astype(int), random_state=42)\n\nm_raw = HistGradientBoostingClassifier(\n    max_iter=60, max_bins=32, max_leaf_nodes=15, min_samples_leaf=5, early_stopping=False, random_state=42\n).fit(X_raw[tr_i], y[tr_i])\nm_mit = HistGradientBoostingClassifier(\n    max_iter=60, max_bins=32, max_leaf_nodes=15, min_samples_leaf=5, early_stopping=False, random_state=42\n).fit(X_mitigated[tr_i], y[tr_i])\n\ntail_mask_te = amount[te_i] > crit_thresh\nprint(\"=== Diagnostik Kuantisasi 255-Bin & Titik Buta Bin Ekor pada Fitur Pareto ===\")\nprint(f\"Uniform Binning  (255) : {len(np.unique(unif_bins)):3d}/255 bin aktif | {pct_in_bin0_unif:5.1f}% populasi terjebak di Bin 0!\")\nprint(f\"Quantile Binning (255) : {len(np.unique(quant_bins)):3d}/255 bin aktif | {pct_in_bin0_quant:5.2f}% populasi di Bin 0 (seimbang)\")\nprint(f\"Rentang Bin 254 (top 0.39%): [{tail_vals.min():,.1f}, {tail_vals.max():,.1f}] (rasio max/min={tail_vals.max()/tail_vals.min():.1f}x)\")\nprint(\"-\" * 82)\nprint(f\"HistGBDT Fitur Mentah (32-bin) | PR-AUC={average_precision_score(y[te_i], m_raw.predict_proba(X_raw[te_i])[:,1]):.4f} | Tail Recall={recall_score(y[te_i][tail_mask_te], m_raw.predict(X_raw[te_i][tail_mask_te]), zero_division=0):.3f}\")\nprint(f\"HistGBDT + Flag Ambang AML     | PR-AUC={average_precision_score(y[te_i], m_mit.predict_proba(X_mitigated[te_i])[:,1]):.4f} | Tail Recall={recall_score(y[te_i][tail_mask_te], m_mit.predict(X_mitigated[te_i][tail_mask_te]), zero_division=0):.3f}\")",
          "expectedOutput": "=== Diagnostik Kuantisasi 255-Bin & Titik Buta Bin Ekor pada Fitur Pareto ===\nUniform Binning  (255) :  20/255 bin aktif |  87.2% populasi terjebak di Bin 0!\nQuantile Binning (255) : 255/255 bin aktif |  0.40% populasi di Bin 0 (seimbang)\nRentang Bin 254 (top 0.39%): [6,908.4, 95,554.7] (rasio max/min=13.8x)\n----------------------------------------------------------------------------------\nHistGBDT Fitur Mentah (32-bin) | PR-AUC=0.3401 | Tail Recall=0.714\nHistGBDT + Flag Ambang AML     | PR-AUC=0.4689 | Tail Recall=1.000",
