          "code": "import itertools\nimport numpy as np\n\n# 1) Bukti Numerik Teorema Fisher (1958): Split Kategorikal Optimal O(K log K) == Brute Force O(2^K)\nrng = np.random.default_rng(154)\nK = 8\nlam = 1.5\nH_cats = rng.uniform(15.0, 80.0, size=K)\ntrue_rates = np.array([-0.65, 0.42, -0.18, 0.75, -0.50, 0.12, 0.60, -0.30])\nG_cats = H_cats * true_rates  # gradien teregularisasi per kategori\n\nG_tot, H_tot = float(G_cats.sum()), float(H_cats.sum())\nparent_score = (G_tot ** 2) / (H_tot + lam)\n\n# A) Metode Fisher O(K log K): urutkan berdasarkan rasio G_c / (H_c + lam), lalu pindai K-1 potongan\nratios = G_cats / (H_cats + lam)\norder = np.argsort(ratios)\nbest_fisher_gain, best_fisher_left = -1.0, frozenset()\nfor split_pos in range(1, K):\n    left_idx = order[:split_pos]\n    GL, HL = float(G_cats[left_idx].sum()), float(H_cats[left_idx].sum())\n    GR, HR = G_tot - GL, H_tot - HL\n    gain = 0.5 * ((GL ** 2) / (HL + lam) + (GR ** 2) / (HR + lam) - parent_score)\n    if gain > best_fisher_gain:\n        best_fisher_gain = gain\n        best_fisher_left = frozenset(int(c) for c in left_idx)\n\n# B) Brute-Force Eksponensial: uji SEMUA 2^(K-1) - 1 = 127 partisi biner tak kosong\nbest_bf_gain, best_bf_left = -1.0, frozenset()\nn_bf_evals = 0\nfor r in range(1, K):\n    for comb in itertools.combinations(range(K), r):\n        if 0 not in comb:\n            continue  # hindari simetri duplikat (L, R) vs (R, L)\n        n_bf_evals += 1\n        idx = list(comb)\n        GL, HL = float(G_cats[idx].sum()), float(H_cats[idx].sum())\n        GR, HR = G_tot - GL, H_tot - HL\n        gain = 0.5 * ((GL ** 2) / (HL + lam) + (GR ** 2) / (HR + lam) - parent_score)\n        if gain > best_bf_gain:\n            best_bf_gain = gain\n            best_bf_left = frozenset(idx)\n\n# Samakan representasi himpunan (komplemen ekuivalen)\nmatch_partition = (best_fisher_left == best_bf_left) or (best_fisher_left == frozenset(range(K)) - best_bf_left)\n\n# 2) Simulasi Routing Native Missing Value (Bin ke-255) pada MNAR (NaN berisiko jauh lebih tinggi)\nG_L_obs, H_L_obs = -18.0, 45.0   # anak kiri: gradien negatif (risiko tinggi)\nG_R_obs, H_R_obs = +22.0, 55.0   # anak kanan: gradien positif (risiko rendah)\nG_miss, H_miss = -14.0, 20.0     # sampel NaN MNAR memiliki profil risiko tinggi seperti anak kiri!\nG_all = G_L_obs + G_R_obs + G_miss\nH_all = H_L_obs + H_R_obs + H_miss\npar_all = (G_all ** 2) / (H_all + lam)\n\ngain_miss_left = 0.5 * (((G_L_obs + G_miss) ** 2) / (H_L_obs + H_miss + lam) + (G_R_obs ** 2) / (H_R_obs + lam) - par_all)\ngain_miss_right = 0.5 * ((G_L_obs ** 2) / (H_L_obs + lam) + ((G_R_obs + G_miss) ** 2) / (H_R_obs + H_miss + lam) - par_all)\nroute_dir = \"KIRI (missing_go_to_left=True)\" if gain_miss_left >= gain_miss_right else \"KANAN (missing_go_to_left=False)\"\n\nprint(\"=== Verifikasi Teorema Fisher (O(K log K)) vs Brute Force (2^(K-1)-1 Partisi) ===\")\nprint(f\"Evaluasi Split: Fisher={K - 1} kandidat vs Brute-Force={n_bf_evals} partisi (K={K})\")\nprint(f\"Best Gain Fisher={best_fisher_gain:.6f} vs Brute-Force={best_bf_gain:.6f} | Partisi Identik={match_partition}\")\nprint(f\"Subset Kiri Optimal Fisher: {sorted(best_fisher_left)}\")\nprint(\"=== Routing Native NaN (Bin 255) pada Sinyal MNAR ===\")\nprint(f\"Gain(NaN -> Kiri)={gain_miss_left:.4f} vs Gain(NaN -> Kanan)={gain_miss_right:.4f} => Arah Dipilih: {route_dir}\")",
